//! What the idempotent consumers call: Kafka delivers at least once, so the same event can arrive twice.
//! Each handling records the event in `processed_events`, in the transaction of the handler.
//!
//! @generated by service-builder. Do not edit: changes are overwritten on the next export.

use std::time::Duration;

use anyhow::Result;
use sqlx::PgPool;

/// How long a handled event is remembered. Kafka redelivers within hours, an outbox relay within minutes.
pub const RETENTION_DAYS: i32 = 7;

/// The table of the events already handled, created with the schema of the service.
pub const CREATE_TABLE: &str = "CREATE TABLE IF NOT EXISTS processed_events (consumer TEXT NOT NULL, event_id TEXT NOT NULL, processed_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (consumer, event_id))";

/// Records the event as handled by `consumer`. `false`: it already was, skip it.
///
/// Call it inside the transaction of the handler: if the handler fails, the record is rolled back with
/// the rest and the retry handles the event for real. Two deliveries racing on the same event cannot both
/// win: the second waits for the first to commit (it then loses) or to roll back (it then wins).
pub async fn first_time(
    tx: &mut sqlx::PgConnection,
    consumer: &str,
    event_id: &str,
) -> Result<bool> {
    let inserted = sqlx::query(
        "INSERT INTO processed_events (consumer, event_id) VALUES ($1, $2) ON CONFLICT DO NOTHING",
    )
    .bind(consumer)
    .bind(event_id)
    .execute(tx)
    .await?
    .rows_affected();
    Ok(inserted == 1)
}

/// Forgets the events handled more than [`RETENTION_DAYS`] days ago.
pub async fn purge(db: &PgPool) -> Result<u64> {
    let result = sqlx::query(
        "DELETE FROM processed_events WHERE processed_at < now() - make_interval(days => $1)",
    )
    .bind(RETENTION_DAYS)
    .execute(db)
    .await?;
    Ok(result.rows_affected())
}

/// Purges every hour, from now on. A failure is logged and the loop goes on.
pub fn spawn_purge(db: PgPool) -> tokio::task::JoinHandle<()> {
    tokio::spawn(async move {
        let mut ticker = tokio::time::interval(Duration::from_secs(3600));
        loop {
            ticker.tick().await;
            match purge(&db).await {
                Ok(rows) => tracing::debug!(rows, "processed events purged"),
                Err(e) => tracing::warn!(error = %e, "cannot purge the processed events"),
            }
        }
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    static TABLE: tokio::sync::OnceCell<()> = tokio::sync::OnceCell::const_new();

    /// Needs a database: `EDA_TEST_DATABASE_URL=postgres://... cargo test -p eda-runtime -- --ignored`.
    /// Each test cleans up the consumers that start with its own prefix, so that they can run side by side.
    async fn database(prefix: &str) -> PgPool {
        let url = std::env::var("EDA_TEST_DATABASE_URL").expect("EDA_TEST_DATABASE_URL");
        let db = PgPool::connect(&url).await.unwrap();
        // Created once: two `CREATE TABLE IF NOT EXISTS` at the same time can still collide.
        TABLE
            .get_or_init(|| async { sqlx::query(CREATE_TABLE).execute(&db).await.unwrap(); })
            .await;
        sqlx::query("DELETE FROM processed_events WHERE consumer LIKE $1")
            .bind(format!("{prefix}%"))
            .execute(&db)
            .await
            .unwrap();
        db
    }

    #[tokio::test]
    #[ignore = "needs EDA_TEST_DATABASE_URL"]
    async fn an_event_is_handled_once_per_consumer() {
        let db = database("test-once").await;
        let mut tx = db.begin().await.unwrap();
        assert!(first_time(&mut tx, "test-once-a", "e1").await.unwrap());
        assert!(!first_time(&mut tx, "test-once-a", "e1").await.unwrap());
        // Another event, and another consumer of the same event, are not duplicates.
        assert!(first_time(&mut tx, "test-once-a", "e2").await.unwrap());
        assert!(first_time(&mut tx, "test-once-b", "e1").await.unwrap());
        tx.commit().await.unwrap();
        let mut tx = db.begin().await.unwrap();
        assert!(!first_time(&mut tx, "test-once-a", "e1").await.unwrap(), "remembered after the commit");
    }

    #[tokio::test]
    #[ignore = "needs EDA_TEST_DATABASE_URL"]
    async fn a_failed_handling_does_not_count() {
        let db = database("test-fail").await;
        let mut tx = db.begin().await.unwrap();
        assert!(first_time(&mut tx, "test-fail", "e1").await.unwrap());
        tx.rollback().await.unwrap();
        // The handler failed: the retry must handle the event for real.
        let mut tx = db.begin().await.unwrap();
        assert!(first_time(&mut tx, "test-fail", "e1").await.unwrap());
    }

    #[tokio::test]
    #[ignore = "needs EDA_TEST_DATABASE_URL"]
    async fn two_deliveries_at_once_cannot_both_win() {
        let db = database("test-race").await;
        let mut first = db.begin().await.unwrap();
        assert!(first_time(&mut first, "test-race", "e1").await.unwrap());
        // The second delivery waits for the first one...
        let other = db.clone();
        let second = tokio::spawn(async move {
            let mut tx = other.begin().await.unwrap();
            let won = first_time(&mut tx, "test-race", "e1").await.unwrap();
            tx.commit().await.unwrap();
            won
        });
        tokio::time::sleep(Duration::from_millis(300)).await;
        assert!(!second.is_finished(), "it should be waiting on the row of the first");
        // ...and loses when the first commits.
        first.commit().await.unwrap();
        assert!(!second.await.unwrap());
    }

    #[tokio::test]
    #[ignore = "needs EDA_TEST_DATABASE_URL"]
    async fn old_events_are_forgotten() {
        let db = database("test-old").await;
        sqlx::query("INSERT INTO processed_events (consumer, event_id, processed_at) VALUES ('test-old', 'old', now() - interval '8 days'), ('test-old', 'recent', now() - interval '6 days')")
            .execute(&db)
            .await
            .unwrap();
        purge(&db).await.unwrap();
        let mut tx = db.begin().await.unwrap();
        assert!(first_time(&mut tx, "test-old", "old").await.unwrap(), "past the retention: forgotten");
        assert!(!first_time(&mut tx, "test-old", "recent").await.unwrap(), "within it: remembered");
    }
}
